1	<script setup>
2	import { useRoute } from 'vue-router'
3	
4	const route = useRoute()
5	
6	const tabs = [
7	  { name: 'Dashboard', to: '/', icon: 'pi pi-chart-bar', label: 'Dashboard' },
8	  { name: 'Holdings', to: '/holdings', icon: 'pi pi-briefcase', label: 'Holdings' },
9	  { name: 'Watchlist', to: '/watchlist', icon: 'pi pi-eye', label: 'Watchlist' },
10	  { name: 'Transactions', to: '/transactions', icon: 'pi pi-list', label: 'History' },
11	  { name: 'Profile', to: '/profile', icon: 'pi pi-user', label: 'Profile' },
12	]
13	
14	function isActive(tab) {
15	  if (tab.to === '/') return route.path === '/'
16	  return route.path.startsWith(tab.to)
17	}
18	</script>
19	
20	<template>
21	  <nav class="bottom-nav">
22	    <RouterLink
23	      v-for="tab in tabs"
24	      :key="tab.name"
25	      :to="tab.to"
26	      class="nav-item"
27	      :class="{ active: isActive(tab) }"
28	    >
29	      <i :class="tab.icon" />
30	      <span>{{ tab.label }}</span>
31	    </RouterLink>
32	  </nav>
33	</template>
34	
